from lib import runs
import resnums as N
from resnums import f, sg, ref, P1, P2, P4, S

def abstract():
    xr, rr = ref("XGB", "random", "rho_gap"), ref("RF", "random", "rho_gap")
    return ("Global SHAP rankings are often read as a description of encrypted traffic, but a ranking learned in one observation context need not hold in another. "
            "We test this on the seven-class application task of the ISCX VPN-nonVPN benchmark, using TreeSHAP to explain Random Forest and XGBoost models trained separately on Non-VPN and VPN flows. "
            f"On the primary split the rankings agree only in part (Spearman ρ {f(P1['cross_RF']['rho'],2)} for Random Forest and {f(P1['cross_XGB']['rho'],2)} for XGBoost, with half-split means of {f(ref('RF','random','rho_cross'),2)} and {f(ref('XGB','random','rho_cross'),2)}; rank-biased overlap {f(P1['cross_RF']['rbo'],2)} and {f(P1['cross_XGB']['rbo'],2)}), and each model keeps three of its five leading features. "
            f"Against flow-level random half-splits of one context, the within-minus-cross gap in ρ is {f(xr,2)} for XGBoost and {f(rr,2)} for Random Forest (means over 11 repeats; SD {f(ref('XGB','random','rho_gap','sd'),2)} and {f(ref('RF','random','rho_gap','sd'),2)}), and a permutation null that keeps each context's class mix gives {sg(ref('XGB','null','rho_gap'),3)} and {sg(ref('RF','null','rho_gap'),3)}. "
            f"The gap does not survive a stricter reference. When the halves are built from whole clusters of similar flows, a proxy for capture sessions, it falls to {f(ref('XGB','grouped10','rho_gap'),2)}–{f(ref('RF','grouped10','rho_gap'),2)} with clusters of about ten flows and to {f(min(ref('XGB','grouped35','rho_gap'),ref('RF','grouped35','rho_gap')),2)}–{f(max(ref('XGB','grouped35','rho_gap'),ref('RF','grouped35','rho_gap')),2)} with clusters of about 35, so once related flows are kept together the cross-context disagreement is hardly larger than the disagreement between groups of related flows within one context. "
            "Resampling a context to the other context's class mix moves its ranking toward the other context's by at most 0.02 in ρ. "
            f"A model trained in one context reaches only {f(min(P2['transfer_XGB_novpn_to_vpn']['f1'],P2['transfer_RF_novpn_to_vpn']['f1']),2)}–{f(max(P2['transfer_XGB_vpn_to_novpn']['f1'],P2['transfer_RF_vpn_to_novpn']['f1']),2)} macro F1 in the other, whereas reusing the other context's SHAP-selected Top-10 feature list changes macro F1 by {topk_range(10)} on average. "
            "The design is observational and the processed data carry no session identifiers, so none of these differences can be attributed to tunnelling.")

def topk_range(k):
    d = N.TK[N.TK.k == k].groupby(["model", "target"])["diff"].mean()
    return f"{sg(-d.max(),3)} to {sg(-d.min(),3)}"   # transferred minus own

def front(D, O):
    for i in range(0, 6): D.add(O[i])
    D.raw('<w:p><w:pPr><w:spacing w:before="240" w:after="120" w:line="264" w:lineRule="auto"/><w:jc w:val="both"/></w:pPr>'
          '<w:r><w:rPr><w:b/><w:bCs/><w:i/><w:iCs/></w:rPr><w:t>Abstract&#8212;</w:t></w:r>' + runs(abstract()) + '</w:p>')
    D.add(O[7])

def intro(D, O):
    D.h1("I. INTRODUCTION")
    for i in (9, 10, 11, 12): D.add(O[i])
    D.p("The VPN and Non-VPN parts of the dataset allow model reliance to be compared across two observation contexts that use the same labels and the same feature encoding. The comparison is observational: class composition and capture sessions also differ between the parts. Cross-context disagreement therefore means little on its own. It has to be set against the disagreement between models trained on different data from the same context, and that reference is only as good as the independence of the data it is built from. Flows from one capture session are often near copies of each other, so a random split of one context puts related flows on both sides and can make within-context agreement look higher than it would be across sessions. Earlier classification studies have concentrated on predictive accuracy, and explanation consistency needs an assessment of its own (Section II). In this paper we ask whether models lean on similar flow features when making the same predictions for VPN and Non-VPN traffic, how that disagreement compares with within-context references of increasing strictness, and whether it has practical consequences. Telling VPN from Non-VPN traffic is not the classification target here.")
    D.p("The work makes four contributions. First, it compares separately trained classifiers against three within-context references: flow-level random half-splits, half-splits that keep whole clusters of similar flows together as a proxy for capture sessions, and a permutation null in which flows are reassigned at random between two pseudo-contexts. Second, it tests the class-mix explanation directly by resampling each context to the other's class mix. Third, it measures two practical consequences: the cost of applying a trained model to the other context, and the cost of reusing the other context's SHAP-selected feature list. Fourth, it aggregates importance into semantic feature families and reports a set of sensitivity checks. No new classifier, attribution method or dataset is proposed. Section II reviews related work and Section III describes the data and its audit. Section IV gives the methodology and Sections V to IX the results. Section X summarises and discusses them, Section XI sets out threats to validity, and Section XII concludes.")

def related(D, O):
    D.h1("II. RELATED WORK")
    for i in range(15, 27): D.add(O[i])
    D.add(O[27])
    D.p("SHAP has been used before to explain the cross-domain performance of network intrusion detection [55], and explainable traffic-analysis studies have looked at encrypted-traffic datasets, ISCX VPN-nonVPN among them [56]. Our question is narrower. Within the shared ISCX feature schema and the same seven-class application task, do the global SHAP rankings of VPN and Non-VPN traffic differ by more than the rankings of models trained on different, and suitably independent, data from one context? We also aggregate importance into six predefined feature families and measure what happens to predictive performance when a trained model, or a Top-k feature list, is carried from one context to the other. The contribution is tied to this benchmark and this evaluation design, and it is not offered as the first SHAP study to span domains.")

def note(D, text):
    D.raw('<w:p><w:pPr><w:keepLines/><w:spacing w:before="40" w:after="160" w:line="230" w:lineRule="auto"/><w:jc w:val="both"/></w:pPr><w:r><w:rPr><w:i/><w:iCs/><w:sz w:val="17"/><w:szCs w:val="17"/></w:rPr><w:t xml:space="preserve">Note. </w:t></w:r>' + runs(text, size=17) + '</w:p>')

def figcap(D, n, text):
    D.raw(f'<w:p><w:pPr><w:keepLines/><w:spacing w:after="200" w:line="240" w:lineRule="auto"/><w:jc w:val="both"/></w:pPr><w:r><w:rPr><w:b/><w:bCs/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr><w:t xml:space="preserve">Fig. {n}. </w:t></w:r>' + runs(text, size=20) + '</w:p>')

def data(D, O):
    A = {c: P1[f"audit_{c}"] for c in ("novpn", "vpn")}
    D.h1("III. DATASET AND EXPERIMENTAL SETUP")
    D.h2("A. Dataset and Observation Contexts")
    D.p("Our input is the time-related feature release of the ISCX VPN-nonVPN dataset [4], distributed by the Canadian Institute for Cybersecurity at the University of New Brunswick [57]. We use the Scenario A2 files for the 15 s flow timeout (TimeBasedFeatures-Dataset-15s-NO-VPN.arff and TimeBasedFeatures-Dataset-15s-VPN.arff), which hold 8,965 and 9,793 flows. We removed exact duplicate rows, identical in all 23 features and the label, within each context (271 and 413 rows), leaving 8,694 Non-VPN and 9,380 VPN flows. We then split each context once into stratified 80% training and 20% test partitions. This split is our own and is not supplied with the dataset; we call it the primary split and its parts the primary partitions. We checked that every processed record maps back to a row of the original ARFF files.")
    D.p(f"Some feature vectors still occur more than once inside a training partition after this step: {A['novpn']['dup_vectors_train']} vectors account for {A['novpn']['dup_rows_train']} Non-VPN training rows ({A['novpn']['dup_rows_train']-A['novpn']['dup_vectors_train']} surplus rows) and {A['vpn']['dup_vectors_train']} vectors for {A['vpn']['dup_rows_train']} VPN training rows ({A['vpn']['dup_rows_train']-A['vpn']['dup_vectors_train']} surplus rows). Every one of them carries more than one label, which is why exact-row deduplication kept them. They are label conflicts, not copies, and like the collisions in Section III-C they mark flows that the 23 features cannot separate.")
    D.p("Every record is one flow, described by the 23 features in Table I. These cover flow duration, rates of bytes and packets, inter-arrival-time (IAT) statistics in the forward, backward and combined directions, and statistics of active and idle periods. Each record carries one of seven application labels: BROWSING (0), CHAT (1), FT (file transfer, 2), MAIL (3), P2P (4), STREAMING (5) and VOIP (6). Both contexts use the same feature definitions and label set. The target in each context is the application category, so we solve two separate seven-class problems. No model is trained on data from both contexts, and none predicts the context.")
    for i in (32, 33, 34): D.add(O[i])
    D.tab_n += 1
    note(D, f"The feature set is the time-related representation introduced by Draper-Gil et al. [4]. IAT values and active/idle lengths are stored in microseconds. Where a statistic cannot be defined for a flow (a flow with no backward packets, say, or with no idle period), the files hold −1; Section IV-H explains how this sentinel is treated. Every entry below −1 in the files belongs to min_flowiat ({A['novpn']['below_m1_entries']} Non-VPN and {A['vpn']['below_m1_entries']} VPN training flows and 17 and 12 test flows, as low as −1,247); Section VI-E examines them.")
    D.h2("B. Class Distributions")
    cm = P1["classmix"]
    D.p(f"Table II and Fig. 1 list how many flows of each class sit in the primary partitions. Inside each context, training and test look alike: the total variation distance between them is 0.001 for both Non-VPN and VPN, as expected from the stratified split. Across contexts the picture changes. FT accounts for 9.9% of Non-VPN training flows and 20.1% of VPN training flows. VOIP goes the other way, from 32.5% down to 24.2%. MAIL is the smallest class in both contexts, though it grows from 2.7% to 4.6%. The two training distributions sit {f(cm['tvd'])} apart in total variation distance, and a chi-square homogeneity test gives χ^{{2}} = {cm['chi2']:.1f} on 6 degrees of freedom (p < 0.001), with Cramér's V = {f(cm['cramer_v'])}. In Non-VPN the largest class is {cm['imb_ratio'][0]:.1f} times the size of the smallest; in VPN the ratio is {cm['imb_ratio'][1]:.1f}. A model fitted to one class mix may hand out attribution differently from a model fitted to another, even if the flows inside each class look the same, so we treat class mix as a possible confounder and test it directly in Section VI-D.")
    D.p("BROWSING is the exception to these differences. It has exactly 2,500 flows in both contexts (2,000 training and 500 test), while every other class differs in size between contexts. The cap comes from the dataset release. Every Scenario A2 file, for all four flow timeouts (15, 30, 60 and 120 s) and both contexts, contains exactly 2,500 BROWSING flows, and every Non-VPN file contains exactly 1,000 P2P flows, while the other classes vary with the timeout. None of the 2,500 BROWSING rows in the two 15 s files is an exact duplicate, so our deduplication kept all of them; 59 of the 1,000 Non-VPN P2P rows were duplicates, leaving 941. The frequencies of these two classes are therefore set by how the benchmark was assembled, not by the traffic, and we do not interpret them. They do contribute to the class-mix difference tested in Section VI-D.")
    D.tab_n += 1
    D.add(O[38])
    D.raw('<w:p><w:pPr><w:keepNext/><w:spacing w:after="80" w:line="240" w:lineRule="auto"/><w:jc w:val="center"/></w:pPr>' + runs("Dataset statistics for the two observation contexts (primary partitions, verified counts)", size=20) + '</w:p>')
    D.add(O[40])
    note(D, "An exact collision is a unique 23-dimensional feature vector found in both partitions after duplicate rows within each partition have been dropped; their labels disagree across partitions. The matched-subset rows give the per-class sizes used for class-matched training in Section VI-D.")
    D.add(O[42]); D.fig_n += 1
    figcap(D, 1, "Class make-up of the primary partitions for the two observation contexts. Each bar is the percentage of a partition taken by one class, with its count shown as a label. (a) Training partitions. (b) Test partitions. Within a context, training and test proportions are almost identical; between contexts they differ, most clearly for FT and VOIP.")
    D.h2("C. Leakage, Near-Duplicate and Grouping Audit")
    nn = {c: P1[f"nn_{c}"] for c in ("novpn", "vpn")}
    D.p(f"We audited the partitions before training anything. Once repeated rows inside a partition are dropped, Non-VPN keeps {A['novpn']['unique_train']:,} distinct feature vectors in training and {A['novpn']['unique_test']:,} in test, and exactly one vector appears on both sides. VPN keeps {A['vpn']['unique_train']:,} and {A['vpn']['unique_test']:,}, with thirteen shared. Every shared vector has one label in training and another in test, so we call them exact feature-vector collisions, not copies. Because the labels disagree, memorising these rows cannot raise test accuracy. They make up at most 0.7% of VPN test rows, and we left them in.")
    D.p(f"Near duplicates needed a different check. On standardised raw features the nearest-neighbour distances are tiny (Non-VPN median test-to-train distance {f(nn['novpn']['std']['test_to_train'],4)} standard deviations), because a handful of extreme values dominate each heavy-tailed feature. We therefore repeated the audit after a log transform, log(x + 2) with values clipped at −1 so that the sentinel maps to zero, followed by standardisation, and after a rank (quantile) transform, both fitted on training data only. For each record we measured the distance to the closest record on the other side of the split and to the closest other record on its own side. Under the log transform the median test-to-training distance is {f(nn['novpn']['log']['test_to_train'])} for Non-VPN against {f(nn['novpn']['log']['train_to_train'])} from training to training; for VPN the values are {f(nn['vpn']['log']['test_to_train'])} and {f(nn['vpn']['log']['train_to_train'])}. The rank transform gives {f(nn['novpn']['rank']['test_to_train'])} and {f(nn['novpn']['rank']['train_to_train'])} (Non-VPN) and {f(nn['vpn']['rank']['test_to_train'])} and {f(nn['vpn']['rank']['train_to_train'])} (VPN).")
    cv = lambda m, c, k: f(P1[f"cv_{m}_{c}_{k}"])
    D.p(f"Test records are as close to the training data as training records are to each other. That is what a random split of correlated flows produces, so the audit rules out gross copying but not dependence between related flows. As a proxy for session grouping we clustered the log-transformed training flows of each context into 50 k-means clusters and compared five-fold cross-validation that keeps clusters intact with ordinary stratified five-fold cross-validation. On Non-VPN, macro F1 falls from {cv('XGB','novpn','strat')} to {cv('XGB','novpn','grouped')} for XGBoost and from {cv('RF','novpn','strat')} to {cv('RF','novpn','grouped')} for Random Forest; on VPN, from {cv('XGB','vpn','strat')} to {cv('XGB','vpn','grouped')} and from {cv('RF','vpn','strat')} to {cv('RF','vpn','grouped')}. Holding out whole clusters also asks a model to extrapolate to unseen regions of feature space, so this drop overstates what session grouping alone would cost, but performance clearly depends on having similar flows on both sides of a split.")
    D.p("The processed files carry no session or capture identifiers, so a true group-aware split cannot be built from them. The raw packet captures would allow one: flows could be regenerated with the original feature extractor and split by capture file. They are distributed separately as large PCAP archives, and regenerating the 23 features from them was beyond what this study could do while keeping the published feature set unchanged. We therefore keep the primary partitions for single fits and use cluster-grouped half-splits at three granularities as within-context references (Section IV-D), and we return to this limitation in Section XI.")
    D.h2("D. Models and Implementation")
    D.p(f"Two tree ensembles carry the analysis because they treat correlated inputs differently. Random Forest [48] averages many deep trees, and each split chooses from a random subset of features. XGBoost [49] builds shallower trees in sequence, with regularisation. Both are explained with TreeSHAP. Extra Trees [50] appears only in the robustness checks of Section IX. An earlier version also reported multinomial Logistic Regression as a performance baseline. Even with a log(x + 2) transform it reached only {f(P1['LRlog_novpn']['f1'])} (Non-VPN) and {f(P1['LRlog_vpn']['f1'])} (VPN) macro F1 against 0.85–0.93 for the ensembles, it was never explained, and it added nothing to the explanation analysis, so we have dropped it.")
    D.p("Configurations are listed in Table III and do not change between contexts. Hyperparameters were set once and not tuned; Section IX reports how far rankings move under other XGBoost settings and seeds. The primary models use random_state 42, and every model in the repeated designs of Section IV-D has its own seed. The code relies on scikit-learn [51] and XGBoost [49], with TreeSHAP from the SHAP library [14]. Every number in this version was produced in one software environment (Table III). The previous version mixed two environments, which made the same XGBoost condition differ by up to 0.011 macro F1 between two tables. Random Forest results are identical in both environments; XGBoost single fits moved by at most 0.006 macro F1 relative to the previous version.")
    env = P1["env"]
    D.table("Model and explanation configurations", [1600, 5826, 1600], [
        ["Model", "Configuration", "Use"],
        ["Random Forest", "200 trees; max_features = sqrt; min_samples_leaf = 1; bootstrap = True; class_weight = None; random_state = 42", "TreeSHAP"],
        ["XGBoost", "200 estimators; multi:softprob, 7 classes; max_depth = 6; learning_rate = 0.1; subsample = 0.8; colsample_bytree = 0.8; min_child_weight = 1; eval_metric = mlogloss; random_state = 42", "TreeSHAP"],
        ["Extra Trees", "500 trees; max_features = sqrt; min_samples_leaf = 1; random_state = 42", "Robustness only"],
        ["TreeSHAP", "Path-dependent primary; interventional robustness with 200 training background records. Random Forest and Extra Trees: class probabilities; XGBoost: class margins", "Ranks and normalised shares"],
    ], note=f"The same hyperparameters are used in both contexts, and all models take the original features. Every result was computed under Python {env['python']}, NumPy {env['numpy']}, pandas {env['pandas']}, scikit-learn {env['sklearn']}, XGBoost {env['xgboost']} and SHAP {env['shap']} on Linux (x86-64). XGBoost was run single-threaded; refitting with two threads gave identical predictions.")
